__NUXT_JSONP__("/ru/school-calendar", {data:[{details:{slug:"ru",pageTitle:"Школьный календарь | Mentor Language Institute",pageDescription:"День начала программы может быть разный для студентов статуса F1 и без статуса F1",title:"Школьный календарь",calendar:[{year:"2026",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2026.PNG"},{year:"2027",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2027.png"}],notes:["\u003Cfont color=\"#FECC13\"\u003EЖелтый\u003C\u002Ffont\u003E: День Начала Программы (Модуля)\u003Cbr \u002F\u003E\u003Cfont color=\"”#008000”\"\u003EЗеленый\u003C\u002Ffont\u003E：Государственный праздник (Каникулы)"],schoolCalendar:{title:"Школьный календарь (День Начала Программы)",description:["\u003Cspan class=\"ymarker\"\u003EДень начала программы может быть разный для студентов статуса F1 и без статуса F1\u003C\u002Fspan\u003E"],lists:[{key:"Студенты без статуса F1 это те, у кого нет студенческой визы",value:["Могут начать программу в любой Понедельник. \u003Cbr\u002F\u003E Если понедельник является праздничным днем, то датой начала программы будет вторник на этой неделе."]},{key:"Студенты статуса F1, те которые получили студенческую визу",value:["Могут начать программу в определенные Понедельники. (даты выделенные желтым в календаре). ","\u003C2026\u003E \u003Cbr \u002F\u003E1\u002F20, 2\u002F17, 3\u002F16, 4\u002F13, 5\u002F11, 6\u002F8, 7\u002F6, 8\u002F3, 8\u002F31, 9\u002F28, 10\u002F26, 11\u002F23, 12\u002F21","\u003C2027\u003E\u003Cbr \u002F\u003E 1\u002F25, 2\u002F22, 3\u002F22, 4\u002F19, 5\u002F17, 6\u002F14, 7\u002F12, 8\u002F9, 9\u002F7, 10\u002F4, 11\u002F1, 11\u002F29","\u003C2028\u003E \u003Cbr \u002F\u003E 1\u002F3"]}]},faq:{title:"Часто задаваемые вопросы о датах прибытия в США",lists:[{key:"\u003Cb\u003EQ: За сколько дней до даты начала программы студент может прибыть в США? \u003C\u002Fb\u003E",value:["A: MLI не требует, чтобы наши студенты приезжали в США заранее за определенное количество дней. Тем не менее, наши студенты обычно приезжают в США за 1 или 2 дня до даты начала программы."],note:"Примечание: Иностранным студентам разрешается въезд в США за 30 дней до даты начала обучения."},{key:"\u003Cb\u003EQ: Возможно ли вьехать в общежитие до даты начала программы? \u003C\u002Fb\u003E",value:["A: Да. Мы можем организовать переезд в любой день.\u003Cbr \u002F\u003EЕсли у вас есть другие вопросы, пожалуйста, не стесняйтесь обращаться к нам."]}]},dir:"\u002Fschool-calendar",path:"\u002Fschool-calendar\u002Fru",extension:".json",createdAt:"2026-10-22T16:31:30.877Z",updatedAt:"2026-04-24T11:47:24.336Z"}}],fetch:{},mutations:void 0});